import { PhantomWalletAdapter } from '@solana/wallet-adapter-phantom';
import * as solanaWeb3 from '@solana/web3.js';
import * as splToken from '@solana/spl-token';
import { useContext, useEffect, useMemo, useState } from "react";
import { theme } from "../../styles/theme";
import { ButtonMedium } from '../../styles/common/Button';
import styled from 'styled-components';
import MessageModal from '../modal/MessageModal';
import { walletText } from '../../utils/wallet/walletText';
import { useWalletContext } from '../../contexts/WalletContextProvider';
import { getPhantomEncryptionKey, createSharedSecret, decryptPayload } from '../../utils/ecryptKey';
interface PhantomProvider {
    isPhantom?: boolean;
    connect: () => Promise<{ publicKey: { toString: () => string } }>;
    disconnect: () => Promise<void>;
    on: (event: string, callback: (args: any) => void) => void;
    isConnected: boolean;
    signMessage: (message: Uint8Array) => Promise<{ signature: Uint8Array }>;
    signTransaction: (transaction: any) => Promise<any>;
    publicKey: { toString: () => string } | null;
    network: string;
}
const WalletList = styled.div`
    display:flex;
    align-items:center;
    justify-content:space-between;
    gap:1rem;
    padding: 1rem 1.5rem;
    background: rgba(255, 255, 255, 0.05);
`;

const WalletItem = styled.div`
    display:flex;
    align-items:center;
    gap:1rem;
    @media screen and (max-width : 576px ){
        button { display:none; }
    }    
`;

export default function PhanthomWallet() {
    const [actionType, setActionType] = useState<string>('');
    const [isOpen, setIsOpen] = useState<boolean>(false);
    const walletName = 'Phantom';
    const [provider, setProvider] = useState<PhantomProvider | null>(null);
    const [connected, setConnected] = useState<boolean>(false);
    const [publicKey, setPublicKey] = useState<string | null>(null);
    const [balance, setBalance] = useState<number | null>(null);
    const [isPhantomInstalled, setIsPhantomInstalled] = useState<boolean>(false);
    const [tokenBalances, setTokenBalances] = useState<any[]>([]);
    const { setIsWalletConnected, setWalletName, isWalletConnected } = useWalletContext();
    // Phantom 설치 여부 확인 (웹 & 모바일)
    const [isMobileDevice, setIsMobileDevice] = useState<boolean>(false);

    const phantomAdapter = new PhantomWalletAdapter();

    const detectMobileDevice = () => {
        return /Android|webOS|iPhone|iPad|iPod|BlackBerry|IEMobile|Opera Mini/i.test(
            navigator.userAgent
        );
    };
    const checkForPhantom = async () => {
        try {
            // 모바일 딥링크 감지
            const isMobile = detectMobileDevice();
            setIsMobileDevice(isMobile);
            console.log('isMobile', isMobile);

            if (isMobile) {
                setIsPhantomInstalled(true);
                return;
            }
            // 데스크톱에서는 window.phantom 확인
            // if('phantom' in window){
            //     console.log('window.phantom',window?.phantom?.solana);
            // }
            const isPhantomAvailable = window.phantom?.solana && window.phantom.solana.isPhantom;
            // console.log('isPhantomAvailable',isPhantomAvailable);

            setIsPhantomInstalled(!!isPhantomAvailable);

            if (isPhantomAvailable) {
                const phantom = window.phantom?.solana;
                setProvider(phantom);
                // console.log('phantom', phantom);

                // 이미 연결되어 있는지 확인
                if (phantom.isConnected && phantom.publicKey) {
                    // console.log('connected', phantom.publicKey);

                    setConnected(true);
                    setPublicKey(phantom.publicKey.toString());
                }

                // 이벤트 리스너 설정
                phantom.on("connect", (publicKey: any) => {
                    setConnected(true);
                    setPublicKey(publicKey.toString());
                    console.log('connected', publicKey.toString());
                    localStorage.setItem('publicKey', publicKey.toString());
                    localStorage.setItem('walletName', 'Phantom');
                    setWalletName('Phantom');
                    setIsWalletConnected(true);
                    setIsOpen(true);
                    setActionType('connect');
                });

                phantom.on("disconnect", () => {
                    // console.log('disconnect');

                    setConnected(false);
                    setPublicKey(null);
                });
            } else {
                setActionType('uninstalled');
            }
        } catch (error) {
            console.error("Phantom 확인 중 오류:", error);
        }
    }
    useEffect(() => {
        // URL 파라미터 확인
        const url = new URL(window.location.href);
        const phantomEncryptionPublicKey = url.searchParams.get('phantom_encryption_public_key');
        const nonce = url.searchParams.get('nonce');
        const data = url.searchParams.get('data');

        // Phantom에서 리디렉션된 경우
        if (phantomEncryptionPublicKey && nonce && data) {
            try {
                alert(`Phantom 리디렉션 데이터 수신: ${phantomEncryptionPublicKey.substring(0, 10)}...${nonce.substring(0, 10)}...${data.substring(0, 10)}...`);

                // 저장된 Dapp의 비밀 키 가져오기
                const dappSecretKey = localStorage.getItem('phantom_encryption_secret_key');

                if (!dappSecretKey) {
                    console.error('암호화 비밀 키를 찾을 수 없습니다.');
                    alert('암호화 비밀 키를 찾을 수 없습니다. 다시 연결해주세요.');
                    return;
                }

                // 공유 비밀 생성 - Phantom의 공개키와 Dapp의 비밀키 사용
                const sharedSecret = createSharedSecret(
                    phantomEncryptionPublicKey,  // Phantom의 공개키
                    dappSecretKey                // Dapp의 비밀키
                );

                // 데이터 복호화
                if (sharedSecret) {
                    const decryptedData = decryptPayload(data, nonce, sharedSecret);
                    console.log('복호화된 데이터:', decryptedData);

                    // 연결 성공 처리
                    if (decryptedData && decryptedData.public_key) {
                        // 세션 토큰 저장 (있는 경우)
                        if (decryptedData.session) {
                            localStorage.setItem('phantom_session', decryptedData.session);
                        }

                        // 지갑 연결 상태 업데이트
                        setPublicKey(decryptedData.public_key);
                        setConnected(true);
                        localStorage.setItem('publicKey', decryptedData.public_key);
                        localStorage.setItem('walletName', 'Phantom');
                        setWalletName('Phantom');
                        setIsWalletConnected(true);

                        // 성공 메시지 표시
                        setActionType('connect');
                        setIsOpen(true);
                    } else {
                        alert('복호화된 데이터에 public_key가 없습니다.');
                    }
                }

                // URL에서 파라미터 제거
                window.history.replaceState({}, document.title, window.location.pathname);
            } catch (error: any) {
                console.error('Phantom 연결 응답 처리 오류:', error);
                alert(`Phantom 연결 응답 처리 오류: ${error.message}`);
            }
        }
    }, []);
    useEffect(() => {
        const checkPhantomInstallation = async () => {
            // 모바일 감지
            const isMobile = detectMobileDevice();
            setIsMobileDevice(isMobile);

            if (isMobile) {
                setIsPhantomInstalled(true);
                return;
            }
            // let isPhantomAvailable = false;
            // if('phantom' in window){
            //     isPhantomAvailable = window.phantom?.solana && window.phantom.solana.isPhantom;
            // }
            // if('solana' in window){
            //     isPhantomAvailable = window.solana && window.solana.isPhantom;
            // }
            // 브라우저에서 Phantom 확인 (window.phantom과 window.solana 모두 확인)
            const isPhantomAvailable = window.phantom?.solana && window.phantom.solana.isPhantom;
            console.log('window.phantom', window.phantom, window.solana);
            console.log('Phantom 감지 상태:', isPhantomAvailable);
            setIsPhantomInstalled(!!isPhantomAvailable);

            if (isPhantomAvailable) {
                // Phantom 제공자 설정
                const phantom = window.phantom?.solana || (window as any).solana;
                setProvider(phantom);

                // 이미 연결되어 있는지 확인
                if (phantom.isConnected && phantom.publicKey) {
                    setConnected(true);
                    setPublicKey(phantom.publicKey.toString());
                    setIsWalletConnected(true);
                    setWalletName('Phantom');
                }

                // 이벤트 리스너 설정
                phantom.on("connect", (publicKey: any) => {
                    setConnected(true);
                    setPublicKey(publicKey.toString());
                    console.log('connected', publicKey.toString());
                    localStorage.setItem('publicKey', publicKey.toString());
                    localStorage.setItem('walletName', 'Phantom');
                    setWalletName('Phantom');
                    setIsWalletConnected(true);
                    setIsOpen(true);
                    setActionType('connect');
                });

                phantom.on("disconnect", () => {
                    setConnected(false);
                    setPublicKey(null);
                    setIsWalletConnected(false);
                });
            }
        };
        // 페이지 로드 시 실행
        checkPhantomInstallation();
    }, []);

    // 잔액 조회
    const fetchBalance = async () => {
        console.log('publicKey', publicKey);
        if (!publicKey) return;
        try {
            const connection = new solanaWeb3.Connection(
                // solanaWeb3.clusterApiUrl('mainnet-beta')
                'https://winter-evocative-silence.solana-mainnet.quiknode.pro/04a5e639b0bd9ceeec758a6140dc1aa1b08f62bd', // 또는 다른 신뢰할 수 있는 RPC 제공자
            );

            const balance = await connection.getBalance(
                new solanaWeb3.PublicKey(publicKey)
            );
            // console.log('balance', balance);
            setBalance(balance / solanaWeb3.LAMPORTS_PER_SOL);

        } catch (error) {
            console.error('잔액 조회 실패:', error);
        }
    };
    // 토큰 잔액 조회 함수
    const TOKEN_SYMBOLS: Record<string, string> = {
        'EPjFWdd5AufqSSqeM2qN1xzybapC8G4wEGGkZwyTDt1v': 'USDC',
        'Es9vMFrzaCERmJfrF4H2FYD4KCoNkY11McCe8BenwNYB': 'USDT',
        // 기타 토큰들...
    };
    function getTokenSymbol(mintAddress: string): string {
        return TOKEN_SYMBOLS[mintAddress] || 'Unknown Token';
    }
    const fetchTokenBalances = async (publicKey: string) => {
        try {
            const connection = new solanaWeb3.Connection(
                // solanaWeb3.clusterApiUrl('mainnet-beta')
                'https://winter-evocative-silence.solana-mainnet.quiknode.pro/04a5e639b0bd9ceeec758a6140dc1aa1b08f62bd', // 또는 다른 신뢰할 수 있는 RPC 제공자
            );

            // 사용자의 모든 토큰 계정 조회
            const tokenAccounts = await connection.getParsedTokenAccountsByOwner(
                new solanaWeb3.PublicKey(publicKey),
                {
                    programId: new solanaWeb3.PublicKey(splToken.TOKEN_PROGRAM_ID),
                }
            );

            // 토큰 정보 추출
            const balances = tokenAccounts.value.map(account => {
                const accountData = account.account.data.parsed.info;
                const mintAddress = accountData.mint;
                const amount = accountData.tokenAmount.uiAmount;

                return {
                    mint: mintAddress,
                    symbol: getTokenSymbol(mintAddress), // 토큰 심볼 가져오는 함수 (별도 구현 필요)
                    amount: amount
                };
            }).filter(token => token.amount > 0); // 잔액이 있는 토큰만 표시
            console.log('balances', balances);

            setTokenBalances(balances);
        } catch (error) {
            console.error('토큰 잔액 조회 실패:', error);
        }
    };
    // 지갑 연결 (웹 & 모바일)
    const connectPhantom = async () => {
        if (isWalletConnected) {
            setActionType('alreadyConnected');
            setIsOpen(true);
            return;
        }
        const isMobile = detectMobileDevice();

        // 먼저 Phantom 설치 여부를 다시 확인
        const isPhantomAvailable = window.phantom?.solana && window.phantom.solana.isPhantom;
        setIsPhantomInstalled(!!isPhantomAvailable);

        if (isMobile) {
            // 모바일에서는 딥링크로 Phantom 앱 열기
            // 현재 URL을 콜백으로 사용
            // const currentUrl = encodeURIComponent(window.location.href);
            const encryptionPublicKey = getPhantomEncryptionKey();

            const currentUrl = encodeURIComponent(window.location.href);
            const redirectUrl = encodeURIComponent(window.location.href);

            // 크롬 리다이렉트 URL 생성
            const host = window.location.host;
            const currentPath = window.location.pathname + window.location.search;
            console.log('window.location.href', window.location.href);

            let chromeRedirectUrl;
            if (/iphone|ipad|ipod/.test(navigator.userAgent.toLowerCase())) {
                chromeRedirectUrl = `googlechrome://https://${host}${currentPath}`;
            } else {
                chromeRedirectUrl = `intent://${host}${currentPath}#Intent;scheme=https;package=com.android.chrome;end`;
            }

            const phantomDeepLink = `https://phantom.app/ul/v1/connect?app_url=${currentUrl}&dapp_encryption_public_key=${encryptionPublicKey}&redirect_link=${redirectUrl}`;
            window.location.href = phantomDeepLink;
            return;
        }

        // Phantom이 설치되어 있는지 다시 확인
        if (!isPhantomInstalled) {
            setActionType('uninstalled');
            setIsOpen(true);
            return;
        }

        try {
            const phantom = window.phantom?.solana;
            setProvider(phantom);
            await phantom?.connect();
        } catch (error) {
            console.error('Phantom 연결 오류:', error);
            setActionType('noWallet');
            setIsOpen(true);

            if (isMobileDevice) {
                // 모바일에서는 Phantom 앱으로 이동
                window.location.href = 'https://phantom.app/download';
            } else {
                // alert('Phantom 지갑이 설치되어 있지만 지갑이 생성되지 않았습니다.\n\n1. 브라우저 상단의 Phantom 아이콘을 클릭하세요.\n2. 화면의 안내에 따라 새 지갑을 생성하거나 기존 지갑을 복구하세요.\n3. 지갑 설정이 완료되면 다시 연결을 시도하세요.');

                // // 또는 Phantom 공식 도움말 페이지로 이동
                // if (window.confirm('Phantom 지갑 생성 방법에 대한 도움말 페이지로 이동하시겠습니까?')) {
                //     window.open('https://help.phantom.com/hc/en-us/articles/36482144712083-How-to-Get-Started-with-Phantom-Wallet', '_blank');
                // }
            }
        }
    };
    // 연결되면 잔액 조회
    useEffect(() => {
        if (connected && publicKey) {
            // fetchBalance();
            fetchTokenBalances(publicKey);
        }
    }, [connected, publicKey]);
    return (
        <>
            <WalletList onClick={connectPhantom}>
                <WalletItem>
                    <img src={theme.icon.phantom} alt="phantom" />
                    <p>Phantom</p>
                </WalletItem>
                <WalletItem>
                    {
                        isPhantomInstalled ? (
                            <ButtonMedium bgColor={theme.color.walletBg} textColor={theme.color.mainGreen} borderColor="none">
                                <span>INSTALLED</span>
                            </ButtonMedium>
                        ) : (
                            <ButtonMedium bgColor="rgba(255, 255, 255, 0.15)" textColor={theme.color.gray} borderColor="none">
                                <span>NOT INSTALLED</span>
                            </ButtonMedium>
                        )
                    }
                    <img src={theme.icon.rightArrow} alt="right-arrow" />
                </WalletItem>
            </WalletList>
            <MessageModal action={actionType} isOpen={isOpen} setIsOpen={setIsOpen} walletName={walletName} title={walletText(walletName, actionType)?.title} content={walletText(walletName, actionType)?.content} />
        </>
    );
}