import React from 'react';
import { useWalletContext } from "../../contexts/WalletContextProvider";
import { PhantomWalletAdapter } from '@solana/wallet-adapter-phantom';
// 컴포넌트로 변경
const DisconnectWalletButton: React.FC<{ children?: React.ReactNode }> = ({ children }) => {
  const { setIsWalletConnected, setWalletName } = useWalletContext();
  const phantomAdapter = new PhantomWalletAdapter();

  const handleDisconnect = () => {
    let walletName = localStorage.getItem('walletName');
    if(walletName === 'Phantom'){
      phantomAdapter.on('disconnect', () => {
        setIsWalletConnected(false);
    });
      
    }else if(walletName === 'OKX'){
      let provider = (window as any).okxwallet.solana;
      provider.disconnect();
    }else if(walletName === 'MetaMask'){
      let provider = window.ethereum;
      provider.disconnect();
    }
    localStorage.removeItem('publicKey');
    localStorage.removeItem('walletName');
    setIsWalletConnected(false);
  };
  
  return (
    <li onClick={handleDisconnect}>
      {children || "Disconnect"}
    </li>
  );
};

export default DisconnectWalletButton;